def _resolve_workplan(plan) -> object:
    """Return the workplan from plan, or None if missing."""
    workplan = getattr(plan, "workplan", None)
    if not workplan:
        strategy = getattr(plan, "strategy", None)
        if strategy:
            workplan = getattr(strategy, "parallelisable_workplan", None)
    return workplan


def _collect_tasks(groups: list) -> list:
    """Return a flat list of tasks from all groups."""
    tasks: list = []
    for group in groups or []:
        tasks.extend(getattr(group, "tasks", []) or [])
    return tasks


def _check_task_files(task, seen: set[str], violations: list[str]) -> None:
    """Check file path count and collisions for a single task."""
    fps = getattr(task, "file_paths", None) or []
    if len(fps) != 1:
        violations.append(
            f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)"
        )
    for fp in fps:
        if fp in seen:
            violations.append(f"file collision: {fp} in multiple tasks")
        seen.add(fp)"}

